import { ACADEMY_SCHOOLS, IRRIGATION_LEVEL_FRAMEWORK } from './academyCatalog.js';

const REVISION_DATE = '2026-08-05';

const lesson = (schoolSlug, number, title, objectiveIds, content) => ({
  id: `academy-lesson-${schoolSlug}-${number}`,
  schoolId: `academy-school-${schoolSlug}`,
  courseId: `academy-course-${schoolSlug}-foundations`,
  levelId: `academy-level-${schoolSlug}-1`,
  moduleId: `academy-module-${schoolSlug}-${number}`,
  title,
  learningObjectives: objectiveIds,
  prerequisites: number === 1 ? [] : [`academy-lesson-${schoolSlug}-${number - 1}`],
  estimatedMinutes: 24,
  origin: 'built-in',
  status: 'published',
  revisionDate: REVISION_DATE,
  ...content,
});

const question = (schoolSlug, number, objectiveId, type, prompt, options, correctAnswer, explanation, extras = {}) => ({
  id: `academy-question-${schoolSlug}-${number}`,
  objectiveId,
  topic: schoolSlug,
  difficulty: extras.difficulty || (number % 6 === 0 ? 3 : number % 3 === 0 ? 2 : 1),
  type,
  prompt,
  promptVariants: extras.promptVariants || [],
  scenarioVariables: extras.scenarioVariables || {},
  options: options || [],
  correctAnswer,
  correctAnswerCriteria: extras.correctAnswerCriteria || [],
  explanation,
  misconceptionTags: extras.misconceptionTags || [],
});

function buildCourse(config) {
  const school = ACADEMY_SCHOOLS.find(item => item.slug === config.slug);
  const levelId = `academy-level-${config.slug}-1`;
  return {
    school,
    course: {
      id: `academy-course-${config.slug}-foundations`,
      schoolId: school.id,
      title: config.courseTitle,
      summary: config.courseSummary,
      origin: 'built-in',
      levelIds: [levelId],
    },
    levels: [{
      id: levelId,
      schoolId: school.id,
      courseId: `academy-course-${config.slug}-foundations`,
      number: 1,
      title: config.levelTitle,
      summary: config.levelSummary,
      moduleIds: config.lessons.map((_, index) => `academy-module-${config.slug}-${index + 1}`),
      lessonIds: config.lessons.map((_, index) => `academy-lesson-${config.slug}-${index + 1}`),
      objectiveIds: config.objectives.map(item => item.id),
      vocabularyActivityId: `academy-vocabulary-${config.slug}-1`,
      practiceActivityId: `academy-practice-${config.slug}-1`,
      scenarioAssessmentId: `academy-scenario-${config.slug}-1`,
      fieldLabId: `academy-field-lab-${config.slug}-1`,
      designChallengeId: config.designChallenge ? `academy-design-challenge-${config.slug}-1` : '',
      finalAssessmentId: `academy-final-${config.slug}-1`,
      masteryThreshold: 85,
      status: 'complete',
    }],
    modules: config.lessons.map((item, index) => ({
      id: `academy-module-${config.slug}-${index + 1}`,
      levelId,
      title: item.moduleTitle,
      summary: item.moduleSummary,
      lessonIds: [`academy-lesson-${config.slug}-${index + 1}`],
    })),
    lessons: config.lessons.map((item, index) => lesson(config.slug, index + 1, item.title, item.objectiveIds, item)),
    objectives: config.objectives.map(item => ({ ...item, schoolId: school.id, levelId })),
    vocabulary: {
      id: `academy-vocabulary-${config.slug}-1`,
      levelId,
      title: `${config.levelTitle} vocabulary`,
      objectiveIds: config.objectives.map(item => item.id),
      terms: config.vocabulary,
    },
    practice: {
      id: `academy-practice-${config.slug}-1`,
      levelId,
      objectiveIds: config.objectives.map(item => item.id),
      ...config.practice,
    },
    scenarioAssessment: {
      id: `academy-scenario-${config.slug}-1`,
      levelId,
      title: `${config.levelTitle} scenario assessment`,
      type: 'scenario',
      questionCount: 3,
      objectiveIds: config.objectives.map(item => item.id),
    },
    fieldLab: {
      id: `academy-field-lab-${config.slug}-1`,
      levelId,
      objectiveIds: config.objectives.map(item => item.id),
      ...config.fieldLab,
    },
    designChallenge: config.designChallenge ? {
      id: `academy-design-challenge-${config.slug}-1`,
      levelId,
      objectiveIds: config.objectives.map(item => item.id),
      ...config.designChallenge,
    } : null,
    finalAssessment: {
      id: `academy-final-${config.slug}-1`,
      levelId,
      title: `${config.levelTitle} final assessment`,
      type: 'final',
      questionCount: 5,
      objectiveIds: config.objectives.map(item => item.id),
    },
    questions: config.questions,
  };
}

