export const ACADEMY_CURRICULUM = configs.map(buildCourse);

export const ACADEMY_LEVELS = ACADEMY_CURRICULUM.flatMap(item => item.levels);
export const ACADEMY_LESSONS = ACADEMY_CURRICULUM.flatMap(item => item.lessons);
export const ACADEMY_OBJECTIVES = ACADEMY_CURRICULUM.flatMap(item => item.objectives);
export const ACADEMY_QUESTIONS = ACADEMY_CURRICULUM.flatMap(item => item.questions);

export function academyCourseForSchool(schoolId) {
  return ACADEMY_CURRICULUM.find(item => item.school.id === schoolId) || null;
}

export function academyLevel(levelId) {
  return ACADEMY_LEVELS.find(item => item.id === levelId) || null;
}

export function academyLesson(lessonId) {
  return ACADEMY_LESSONS.find(item => item.id === lessonId) || null;
}

export function academyActivity(activityId) {
  for (const curriculum of ACADEMY_CURRICULUM) {
    const items = [curriculum.vocabulary, curriculum.practice, curriculum.scenarioAssessment, curriculum.fieldLab, curriculum.designChallenge, curriculum.finalAssessment].filter(Boolean);
    const found = items.find(item => item.id === activityId);
    if (found) return found;
  }
  return null;
}

export function academySearchIndex() {
  return ACADEMY_CURRICULUM.flatMap(curriculum => [
    { id: curriculum.school.id, title: curriculum.school.title, detail: curriculum.school.summary, kind: 'School' },
    { id: curriculum.course.id, title: curriculum.course.title, detail: curriculum.course.summary, kind: 'Course' },
    ...curriculum.modules.map(item => ({ id: item.id, title: item.title, detail: item.summary, kind: 'Module' })),
    ...curriculum.lessons.map(item => ({ id: item.id, title: item.title, detail: `${curriculum.school.title} · Lesson`, kind: 'Lesson', text: [item.introduction, item.body, item.keyConcepts, item.vocabulary].flat().join(' ') })),
    ...curriculum.objectives.map(item => ({ id: item.id, title: item.title, detail: `${curriculum.school.title} · Learning objective`, kind: 'Objective' })),
    ...curriculum.vocabulary.terms.map(item => ({ id: `${curriculum.vocabulary.id}-${item.term}`, title: item.term, detail: `${item.definition} · Vocabulary`, kind: 'Vocabulary' })),
  ]);
}

